package dev.hrutvik.filesync.outbox;
import org.junit.jupiter.api.Test; import org.springframework.kafka.core.KafkaTemplate; import java.time.*; import java.util.*; import java.util.concurrent.CompletableFuture; import static org.mockito.ArgumentMatchers.*; import static org.mockito.Mockito.*;
class OutboxRelayTest {
 @Test void marksOnlyAcknowledgedMessagesPublished(){var store=mock(OutboxLeaseStore.class);@SuppressWarnings("unchecked") KafkaTemplate<String,String> kafka=mock(KafkaTemplate.class);when(kafka.send(any(org.apache.kafka.clients.producer.ProducerRecord.class))).thenReturn(CompletableFuture.completedFuture(null));var relay=new OutboxRelay(store,kafka,"changes",10,Duration.ofSeconds(30),Duration.ofSeconds(1));var message=new OutboxMessage(UUID.randomUUID(),"tenant",UUID.randomUUID(),"FILE_VERSION_COMMITTED","{}",Instant.now());relay.publish(message);verify(store).published(eq(message.id()),anyString());verify(store,never()).release(any(),anyString());}
 @Test void releasesLeaseWhenKafkaFails(){var store=mock(OutboxLeaseStore.class);@SuppressWarnings("unchecked") KafkaTemplate<String,String> kafka=mock(KafkaTemplate.class);var failed=new CompletableFuture<org.springframework.kafka.support.SendResult<String,String>>();failed.completeExceptionally(new RuntimeException("broker unavailable"));when(kafka.send(any(org.apache.kafka.clients.producer.ProducerRecord.class))).thenReturn(failed);var relay=new OutboxRelay(store,kafka,"changes",10,Duration.ofSeconds(30),Duration.ofMillis(50));var message=new OutboxMessage(UUID.randomUUID(),"tenant",UUID.randomUUID(),"FILE_VERSION_COMMITTED","{}",Instant.now());relay.publish(message);verify(store).release(eq(message.id()),anyString());verify(store,never()).published(any(),anyString());}
}
